using System;
using System.Drawing;
using System.Linq;
using System.Windows.Forms;
using MyDay.Windows.Core;
namespace MyDay.Windows.UI {
 public sealed class StudioWindow:Form {
  private readonly DiaryBook book;private readonly DiaryEntry entry;private readonly DateTime date;private readonly Func<bool,bool> changed;private readonly string directory;private readonly Action<DateTime> open;private StudioData studio;
  internal readonly TabControl Tabs=new TabControl{Dock=DockStyle.Fill};
  public StudioWindow(DiaryBook book,DiaryEntry entry,DateTime date,string directory,Func<bool,bool> changed,Action<DateTime> open){this.book=book;this.entry=entry;this.date=date;this.changed=changed;this.open=open;this.directory=directory;studio=StudioData.Merge(null,book.Studio)??new StudioData();Text="하루 꾸미기 · 나의 작은 공간";Size=Design.Size(860,700);MinimumSize=Design.Size(680,520);StartPosition=FormStartPosition.CenterParent;Font=Design.Font(10);BackColor=Design.Sidebar;Controls.Add(Tabs);Photos();Room();Moods();Notes();Questions();Privacy();}
  private FlowLayoutPanel Page(string title){var tab=new TabPage(title){BackColor=Design.Sidebar};var p=new FlowLayoutPanel{Dock=DockStyle.Fill,AutoScroll=true,FlowDirection=FlowDirection.TopDown,WrapContents=false,Padding=Design.Pad(16)};tab.Controls.Add(p);Tabs.TabPages.Add(tab);return p;}
  private void NoteText(Control p,string text){var l=Design.Label(text,10);l.MaximumSize=Design.Size(690,0);p.Controls.Add(l);}
  private bool SaveStudio(){StudioData.Validate(studio);book.Studio=StudioData.Merge(null,studio);book.Version=Math.Max(book.Version,9);return changed(false);}
  private void Photos(){var p=Page("1. 사진·스티커");NoteText(p,"사진을 고른 뒤 자르기·회전·프레임·스티커를 적용해요. 적용 전에는 기존 사진을 바꾸지 않아요.");var list=new ComboBox{Width=Design.P(620),DropDownStyle=ComboBoxStyle.DropDownList};var photos=entry.Blocks.Where(b=>b.Kind=="photo"&&b.Photo!=null).ToArray();foreach(var b in photos)list.Items.Add((string.IsNullOrWhiteSpace(b.Text)?"사진":b.Text).Replace('\n',' '));if(photos.Length>0)list.SelectedIndex=0;p.Controls.Add(list);
   PhotoDecorWindow.Add(p,"선택한 사진 꾸미기",()=>{if(list.SelectedIndex<0)return;var b=photos[list.SelectedIndex];using(var editor=new PhotoDecorWindow(b.Photo))if(editor.ShowDialog(this)==DialogResult.OK){string old=b.Photo;b.Photo=editor.Result;b.ValidatedPhoto=null;try{DiaryStore.Validate(book);if(!changed(true)){b.Photo=old;b.ValidatedPhoto=null;}}catch{b.Photo=old;b.ValidatedPhoto=null;throw;}}});
   NoteText(p,"독립 스티커도 일기 블록으로 추가해 자유롭게 배치할 수 있어요.");for(int i=0;i<4;i++){int k=i;PhotoDecorWindow.Add(p,PhotoDecor.Stickers[i]+" 스티커 추가",()=>{if(entry.Blocks.Count>=200)throw new Exception("한 날짜에는 최대 200개 블록을 넣을 수 있어요.");using(var image=PhotoDecor.Sticker(k)){var b=DiaryBlock.Create("photo");b.Title=PhotoDecor.Stickers[k]+" 스티커";b.Photo=PhotoDecor.Encode(image);entry.Blocks.Add(b);if(entry.LayoutMode=="free")DiaryLayout.PlaceNew(entry,b);changed(true);}});}}
  private void Room(){var p=Page("2. 상몬의 방");NoteText(p,"가구를 추가하고 마우스로 움직여요. 가구는 최대 24개예요. 상몬은 모은 옷장 소품을 입고 함께 쉬어요.");var canvas=new RoomCanvas(studio,book,()=>SaveStudio()){Size=Design.Size(650,360)};p.Controls.Add(canvas);var row=new FlowLayoutPanel{Width=Design.P(700),Height=Design.P(92),WrapContents=true};p.Controls.Add(row);for(int i=0;i<6;i++){int k=i;PhotoDecorWindow.Add(row,StudioCatalog.FurnitureNames[i]+" +",()=>{if(studio.Furniture.Count>=24)throw new Exception("가구는 최대 24개예요.");studio.Furniture.Add(new RoomItem{Kind=StudioCatalog.FurnitureKinds[k],X=100+studio.Furniture.Count%5*140,Y=300+studio.Furniture.Count/5*90});if(SaveStudio())canvas.Invalidate();});}PhotoDecorWindow.Add(row,"선택 가구 치우기",()=>{if(canvas.Selected!=null){studio.Furniture.Remove(canvas.Selected);canvas.Selected=null;SaveStudio();canvas.Invalidate();}});PhotoDecorWindow.Add(row,"배경 바꾸기",()=>{studio.RoomTheme=(studio.RoomTheme+1)%3;SaveStudio();canvas.RefreshRoom();});}
  private void Moods(){var p=Page("3. 감정 달력");NoteText(p,"직접 선택한 감정만 표시해요. 날짜를 누르면 그날의 일기로 이동해요.");var month=new DateTimePicker{Format=DateTimePickerFormat.Custom,CustomFormat="yyyy년 MM월",Value=date,Width=Design.P(220)};p.Controls.Add(month);var grid=new TableLayoutPanel{Size=Design.Size(660,380),ColumnCount=7,RowCount=7};for(int i=0;i<7;i++){grid.ColumnStyles.Add(new ColumnStyle(SizeType.Percent,100f/7));grid.RowStyles.Add(new RowStyle(SizeType.Percent,100f/7));}p.Controls.Add(grid);Action render=()=>{grid.Controls.Clear();string[] names={"일","월","화","수","목","금","토"};for(int i=0;i<7;i++)grid.Controls.Add(Design.Label(names[i],10,true),i,0);var first=new DateTime(month.Value.Year,month.Value.Month,1);for(int day=1;day<=DateTime.DaysInMonth(first.Year,first.Month);day++){var target=first.AddDays(day-1);DiaryEntry value;book.Days.TryGetValue(DiaryStore.Key(target),out value);int mood=value==null?-1:Array.IndexOf(StudioCatalog.Moods,value.Mood);var b=Design.Button(day+(value==null?"":"\n"+value.Mood));b.Dock=DockStyle.Fill;b.Margin=Design.Pad(3);b.Font=Design.Font(8);if(mood>=0)b.BackColor=new[]{Color.FromArgb(223,232,213),Color.FromArgb(250,228,164),Color.FromArgb(223,216,236),Color.FromArgb(213,224,237),Color.FromArgb(244,216,221)}[mood];b.Click+=delegate{Close();open(target);};int index=(int)first.DayOfWeek+day-1;grid.Controls.Add(b,index%7,index/7+1);}};month.ValueChanged+=delegate{render();};render();}
  private void Notes(){var p=Page("4. 태그·즐겨찾기");var note=studio.Note(DiaryStore.Key(date));NoteText(p,date.ToString("yyyy-MM-dd")+" · 태그는 쉼표로 구분해요. 최대 10개·각 20자예요.");var tags=new TextBox{Text=string.Join(", ",note.Tags),Width=Design.P(620)};var favourite=new CheckBox{Text="이날을 즐겨찾기",Checked=note.Favourite,AutoSize=true};p.Controls.Add(tags);p.Controls.Add(favourite);PhotoDecorWindow.Add(p,"이날의 분류 저장",()=>{studio.SetNote(new StudioNote{Date=note.Date,Tags=tags.Text.Split(',').Select(t=>t.Trim().TrimStart('#')).Where(t=>t.Length>0).Distinct(StringComparer.OrdinalIgnoreCase).ToList(),Favourite=favourite.Checked});SaveStudio();});NoteText(p,"태그로 찾기 · 아래 결과를 누르면 일기로 이동해요.");var query=new TextBox{Width=Design.P(420)};var only=new CheckBox{Text="즐겨찾기만",AutoSize=true};p.Controls.Add(query);p.Controls.Add(only);var results=new FlowLayoutPanel{Width=Design.P(680),Height=Design.P(280),FlowDirection=FlowDirection.TopDown,WrapContents=false,AutoScroll=true};p.Controls.Add(results);Action search=()=>{results.Controls.Clear();foreach(var n in studio.Pages.Where(n=>(!only.Checked||n.Favourite)&&(query.Text.Trim().Length==0||n.Tags.Any(t=>t.IndexOf(query.Text.Trim().TrimStart('#'),StringComparison.OrdinalIgnoreCase)>=0))).OrderByDescending(n=>n.Date).Take(100)){var item=n;PhotoDecorWindow.Add(results,(item.Favourite?"★ ":"")+item.Date+"  "+string.Join(" ",item.Tags.Select(t=>"#"+t)),()=>{Close();open(DateTime.ParseExact(item.Date,"yyyy-MM-dd",System.Globalization.CultureInfo.InvariantCulture));});}};query.TextChanged+=delegate{search();};only.CheckedChanged+=delegate{search();};search();}
  private void Questions(){var p=Page("5. 오늘의 질문");string question=StudioData.Question(date);NoteText(p,date.ToString("yyyy-MM-dd")+"의 작은 질문");NoteText(p,question);PhotoDecorWindow.Add(p,"이 질문으로 일기 쓰기",()=>{if(entry.Blocks.Any(q=>q.Prompt==question)){MessageBox.Show("이미 이 질문이 일기에 있어요.");return;}if(entry.Blocks.Count>=200)throw new Exception("블록이 가득 찼어요.");var b=DiaryBlock.Create("text");b.Title="오늘의 질문";b.Prompt=question;entry.Blocks.Add(b);if(entry.LayoutMode=="free")DiaryLayout.PlaceNew(entry,b);if(changed(true))Close();});NoteText(p,"질문은 기기 안의 공통 목록에서 날짜별로 골라요. 답변을 외부로 보내지 않아요.");}
  private void Privacy(){var p=Page("6. 일기 잠금");var vault=new PinVault(directory);NoteText(p,"이 기기의 화면 잠금 · 숫자 6~12자리 PIN\n앱을 열 때와 5분 동안 조작하지 않았을 때 잠가요. PIN은 백업에 넣지 않아요.\n화면을 가리는 기능이며 저장 파일 자체를 암호화하지 않아요. PIN을 잊지 않도록 보관해 주세요.");var status=Design.Label(vault.Enabled?"현재 켜짐":"현재 꺼짐",11,true);p.Controls.Add(status);NoteText(p,"현재 PIN (처음 설정할 때는 비워 두세요)");var old=new TextBox{UseSystemPasswordChar=true,MaxLength=12,Width=Design.P(280)};p.Controls.Add(old);NoteText(p,"새 PIN / 새 PIN 확인");var pin=new TextBox{UseSystemPasswordChar=true,MaxLength=12,Width=Design.P(280)};var confirm=new TextBox{UseSystemPasswordChar=true,MaxLength=12,Width=Design.P(280)};p.Controls.Add(pin);p.Controls.Add(confirm);PhotoDecorWindow.Add(p,"PIN 설정·변경",()=>{if(pin.Text!=confirm.Text)throw new Exception("새 PIN 두 입력이 달라요.");vault.Set(old.Text,pin.Text);old.Clear();pin.Clear();confirm.Clear();ScreenPrivacy.Touch();status.Text="현재 켜짐 · 5분 후 자동 잠금";});PhotoDecorWindow.Add(p,"잠금 끄기",()=>{vault.Disable(old.Text);old.Clear();status.Text="현재 꺼짐";});PhotoDecorWindow.Add(p,"지금 잠그기",()=>{changed(false);ScreenPrivacy.Lock();});}
 }
 public sealed class RoomCanvas:Panel {
  private readonly StudioData studio;private readonly Func<bool> save;private readonly MonsterView friend=new MonsterView();private bool dragging;public RoomItem Selected;
  public RoomCanvas(StudioData s,DiaryBook book,Func<bool> save){studio=s;this.save=save;DoubleBuffered=true;friend.Variant=MyDay.Windows.Character.MonsterVariants.FromId(book.CharacterStyle);friend.Equipment=book.Equipment;friend.ShowScene=false;Controls.Add(friend);Resize+=delegate{friend.Bounds=new Rectangle(Width/2-60,Height/2-36,120,110);};RefreshRoom();}
  public void RefreshRoom(){BackColor=new[]{Color.FromArgb(243,235,220),Color.FromArgb(229,222,239),Color.FromArgb(224,233,218)}[studio.RoomTheme];friend.BackColor=BackColor;Invalidate();}
  private Rectangle BoundsOf(RoomItem item){return new Rectangle(item.X*Width/1000,item.Y*Height/1000,Math.Max(44,Width/9),Math.Max(36,Height/6));}
  protected override void OnPaint(PaintEventArgs e){base.OnPaint(e);using(var floor=new SolidBrush(Color.FromArgb(45,140,120,80)))e.Graphics.FillRectangle(floor,0,Height*2/3,Width,Height/3);foreach(var f in studio.Furniture){var r=BoundsOf(f);using(var b=new SolidBrush(f==Selected?Color.FromArgb(245,212,193):Color.FromArgb(251,248,242)))e.Graphics.FillEllipse(b,r);int k=Array.IndexOf(StudioCatalog.FurnitureKinds,f.Kind);TextRenderer.DrawText(e.Graphics,StudioCatalog.FurnitureSymbols[k]+"\n"+StudioCatalog.FurnitureNames[k],Design.Font(11),r,Design.Olive,TextFormatFlags.HorizontalCenter|TextFormatFlags.VerticalCenter);}TextRenderer.DrawText(e.Graphics,"상몬이 방에서 쉬고 있어요",Design.Font(9),new Point(12,12),Design.Olive);}
  protected override void OnMouseDown(MouseEventArgs e){base.OnMouseDown(e);Selected=studio.Furniture.LastOrDefault(f=>BoundsOf(f).Contains(e.Location));dragging=Selected!=null;Capture=dragging;Invalidate();}
  protected override void OnMouseMove(MouseEventArgs e){base.OnMouseMove(e);if(dragging&&Selected!=null){Selected.X=Math.Max(0,Math.Min(900,e.X*1000/Math.Max(1,Width)-50));Selected.Y=Math.Max(0,Math.Min(900,e.Y*1000/Math.Max(1,Height)-50));Invalidate();}}
  protected override void OnMouseUp(MouseEventArgs e){base.OnMouseUp(e);if(dragging){dragging=false;Capture=false;save();}}
 }
}
